     1	/* rt-loop: 1 kHz control loop (prio 50) sharing state with a logger (prio 10)
     2	 * and an uploader (prio 30). Prints one RESULT line after 5 s. */
     3	#include <pthread.h>
     4	#include <sched.h>
     5	#include <semaphore.h>
     6	#include <stdint.h>
     7	#include <stdio.h>
     8	#include <stdlib.h>
     9	#include <time.h>
    10	
    11	#define PERIOD_NS 1000000L
    12	#define RUN_SECONDS 5
    13	#define LATE_NS 1000000L /* a step later than 1 ms counts as a miss */
    14	
    15	static sem_t lock;
    16	#define LOCK() sem_wait(&lock)
    17	#define UNLOCK() sem_post(&lock)
    18	
    19	static volatile int running = 1;
    20	static double setpoint = 1.0, value = 0.0, integ = 0.0, prev_err = 0.0;
    21	
    22	static int64_t now_ns(void) {
    23	    struct timespec t; clock_gettime(CLOCK_MONOTONIC, &t);
    24	    return (int64_t)t.tv_sec * 1000000000LL + t.tv_nsec;
    25	}
    26	static void spin_ns(int64_t ns) { int64_t end = now_ns() + ns; while (now_ns() < end) {} }
    27	
    28	static void *control(void *arg) {
    29	    (void)arg;
    30	    struct timespec next; clock_gettime(CLOCK_MONOTONIC, &next);
    31	    long steps = 0, misses = 0, blocked = 0; int64_t worst = 0, worst_wait = 0, sum_wait = 0;
    32	    int64_t stop = now_ns() + (int64_t)RUN_SECONDS * 1000000000LL;
    33	    while (now_ns() < stop) {
    34	        next.tv_nsec += PERIOD_NS;
    35	        if (next.tv_nsec >= 1000000000L) { next.tv_nsec -= 1000000000L; next.tv_sec++; }
    36	        clock_nanosleep(CLOCK_MONOTONIC, TIMER_ABSTIME, &next, NULL);
    37	        int64_t t0 = now_ns();
    38	        LOCK();
    39	        int64_t w = now_ns() - t0; /* time spent waiting for the lock */
    40	        if (w > worst_wait) worst_wait = w;
    41	        if (w > 1000000) blocked++;
    42	        sum_wait += w;
    43	        double err = setpoint - value;           /* PID step */
    44	        integ += err * 0.001;
    45	        double out = 2.0 * err + 0.5 * integ + 0.01 * (err - prev_err) / 0.001;
    46	        prev_err = err; value += out * 0.001;
    47	        UNLOCK();
    48	        int64_t done = now_ns();
    49	        int64_t late = done - ((int64_t)next.tv_sec * 1000000000LL + next.tv_nsec);
    50	        if (late > worst) worst = late;
    51	        if (late > LATE_NS) misses++;
    52	        steps++;
    53	    }
    54	    running = 0;
    55	    printf("RESULT steps=%ld misses=%ld worst_late_us=%lld lock_waits_over_1ms=%ld worst_lock_wait_us=%lld total_lock_wait_ms=%lld\n",
    56	           steps, misses, (long long)(worst / 1000), blocked, (long long)(worst_wait / 1000), (long long)(sum_wait / 1000000));
    57	    return NULL;
    58	}
    59	
    60	static sem_t kick;
    61	
    62	static void *logger(void *arg) {
    63	    (void)arg;
    64	    while (running) {
    65	        LOCK();
    66	        spin_ns(200000);            /* copy shared state into a log record */
    67	        sem_post(&kick);            /* hand the record to the uploader... */
    68	        spin_ns(200000);            /* ...while still finishing up under the lock */
    69	        UNLOCK();
    70	        struct timespec d = {0, 10000000}; nanosleep(&d, NULL);
    71	    }
    72	    sem_post(&kick);
    73	    return NULL;
    74	}
    75	
    76	static void *uploader(void *arg) {
    77	    (void)arg;
    78	    while (running) { sem_wait(&kick); spin_ns(4000000); /* pretend network send */ }
    79	    return NULL;
    80	}
    81	
    82	static pthread_t start(void *(*fn)(void *), int prio, const char *name) {
    83	    pthread_attr_t a; struct sched_param sp = {.sched_priority = prio}; pthread_t t;
    84	    pthread_attr_init(&a);
    85	    pthread_attr_setinheritsched(&a, PTHREAD_EXPLICIT_SCHED);
    86	    pthread_attr_setschedpolicy(&a, SCHED_FIFO);
    87	    pthread_attr_setschedparam(&a, &sp);
    88	    if (pthread_create(&t, &a, fn, NULL) != 0) { perror("pthread_create"); exit(1); }
    89	    pthread_setname_np(t, name);
    90	    return t;
    91	}
